package com.minimarket.caja.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.caja.dto.*; import com.minimarket.caja.service.CajaTurnoService; import com.minimarket.common.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/caja-turnos") @RequiredArgsConstructor public class CajaTurnoController{private final CajaTurnoService s;@PostMapping("/abrir")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('CAJA_ABRIR')")
    public ApiResponse<CajaTurnoResponseDTO> abrir(@Valid@RequestBody AbrirCajaRequest r){return ApiResponse.ok(s.abrir(r),"Caja abierta");}@GetMapping("/actual/{cajaId}")@PreAuthorize("hasAuthority('CAJA_ABRIR') or hasAuthority('CAJA_CERRAR')")
    public ApiResponse<CajaTurnoResponseDTO> actual(@PathVariable Long cajaId){return ApiResponse.ok(s.actual(cajaId));}@PostMapping("/{id}/cerrar")@PreAuthorize("hasAuthority('CAJA_CERRAR')")
    public ApiResponse<CajaTurnoResponseDTO> cerrar(@PathVariable Long id,@Valid@RequestBody CerrarCajaRequest r){return ApiResponse.ok(s.cerrar(id,r),"Caja cerrada");}}